#include <iostream>
#include <memory>
#include <cstdlib>
static int allocs = 0;
void* operator new(std::size_t n) { ++allocs; return std::malloc(n); }
void operator delete(void* p) noexcept { std::free(p); }
struct S { S(){ std::cout << "ctor\n"; } };
int main() {
    allocs = 0;
    auto p = std::make_shared<S>();                 // 对象+控制块一次分配
    std::cout << "make_shared allocs=" << allocs << '\n';
    allocs = 0;
    auto q = std::shared_ptr<S>(new S());          // new 对象 + 控制块 两次分配
    std::cout << "shared_ptr(new) allocs=" << allocs << '\n';
}
